//! The rule for a lost acknowledgement.
//!
//! When a send's outcome is uncertain, any reconciliation reads are
//! **observations, not proof**. A message with the same text at about the
//! same time does not establish delivery: the outcome stays uncertain unless
//! attribution is established, meaning an identifier the provider ties to
//! this specific request.
//!
//! For `room-cli` 0.43.1 no attribution path is documented: `thread tell`
//! takes no request id, and the `requestId` on a logged user message is
//! generated by the provider. So under 0.43.1 a lost acknowledgement stays
//! uncertain. No reconciliation read is on the allowlist (a provisional
//! choice; the maintainer decides), so OpenWiz makes no observations at all today.

use serde::{Deserialize, Serialize};

use crate::model::Timestamp;

/// Where an observation came from. Neither read is on the allowlist.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ObservationSource {
    /// `thread queue list <id> --json`: a message still queued.
    QueueList,
    /// `thread log <id> --json`: a dispatched user message.
    ThreadLog,
}

/// One message seen on the target after an uncertain send.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Observation {
    pub source: ObservationSource,
    /// The observed message's text has the same SHA-256 as the sent text.
    pub same_text: bool,
    pub observed_at: Timestamp,
    /// An identifier the provider ties to this specific request. None is
    /// documented for 0.43.1, so this is always `false` today.
    pub attributed: bool,
}

/// What the observations show.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum Reconciliation {
    /// Nothing was read: no reconciliation read is allowed.
    NotRead,
    /// Observations only. `matching` counts messages with the same text near
    /// the send's time. They are not proof of delivery.
    Observed { matching: usize, total: usize },
    /// A message the provider ties to this request. Never possible under
    /// 0.43.1.
    Attributed,
}

/// The window around the dispatch in which a same-text message counts as
/// "about the same time".
pub const MATCH_WINDOW_MS: i64 = 120_000;

/// Reconciles an uncertain send dispatched at `dispatched_at` against
/// `observations`. Only an attributed observation establishes delivery;
/// matches on text and time never do.
pub fn reconcile(dispatched_at: Timestamp, observations: &[Observation]) -> Reconciliation {
    if observations.iter().any(|o| o.attributed) {
        return Reconciliation::Attributed;
    }
    let matching = observations
        .iter()
        .filter(|o| {
            o.same_text
                && o.observed_at.0.abs_diff(dispatched_at.0) <= MATCH_WINDOW_MS.unsigned_abs()
        })
        .count();
    Reconciliation::Observed {
        matching,
        total: observations.len(),
    }
}

/// The attribution path for `room-cli` 0.43.1, in words.
pub const ATTRIBUTION_0_43_1: &str =
    "none: room-cli 0.43.1 documents no identifier that ties a delivered message to this request";
